#include <bits/stdc++.h>
using namespace std;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

#define int long long
#define pii pair<int, int>
#define all(v) v.begin(), v.end()
#define sz(v) ((int)v.size())

const int INF = 1e17 + 7;
const int MAX_N = 1001;

int dx[]{0, 0, -1, 1}, dy[]{-1, 1, 0, 0};
vector<int> graph[MAX_N];
bool visited[MAX_N];
int match[MAX_N];

bool is_valid_cell(int x, int y, const vector<string>& grid) {
    int n = (int)grid.size();
    return x >= 0 && y >= 0 && x < n && y < n && grid[x][y] != 'Y' && grid[x][y] != 'Z';
}

vector<vector<int>> bfs_distance(int start_x, int start_y, const vector<string>& grid) {
    int n = (int)grid.size();
    vector<vector<int>> dist(n, vector<int>(n, INF));
    dist[start_x][start_y] = 0;
    deque<pii> q;
    q.push_back({start_x, start_y});
    while (!q.empty()) {
        auto [cx, cy] = q.front();
        q.pop_front();
        for (int dir = 0; dir < 4; dir++) {
            int nx = cx + dx[dir], ny = cy + dy[dir];
            if (!is_valid_cell(nx, ny, grid) || dist[nx][ny] != INF) continue;
            dist[nx][ny] = dist[cx][cy] + 1;
            q.push_back({nx, ny});
        }
    }
    return dist;
}

void read_input_and_build_graph() {
    int n, t;
    cin >> n >> t;
    vector<string> s1(n), s2(n);
    for (int i = 0; i < n; i++) cin >> s1[i];
    for (int i = 0; i < n; i++) cin >> s2[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (s1[i][j] == 'Z') {
                rx = i;
                ry = j;
            }
        }
    }

    vector<vector<int>> reac_dist = bfs_distance(rx, ry, s1);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!is_valid_cell(i, j, s1)) continue;
            vector<vector<int>> from_cell = bfs_distance(i, j, s1);
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (!is_valid_cell(x, y, s1) || from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                    if (from_cell[x][y] == reac_dist[x][y]) {
                        bool can_move = false;
                        for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                            int xto = x + dx[dir_idx];
                            int yto = y + dy[dir_idx];
                            if (!is_valid_cell(xto, yto, s1) || from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                            can_move = true;
                        }
                        if (!can_move) continue;
                    }
                    int max_num1 = s1[i][j] - '0';
                    int max_num2 = s2[x][y] - '0';
                    for (int num1 = 1; num1 <= max_num1; num1++) {
                        for (int num2 = 1; num2 <= max_num2; num2++) {
                            int v1 = 10 * (j + i * 10) + num1;
                            int v2 = 10 * (y + 10 * x) + num2;
                            graph[v1].push_back(v2);
                        }
                    }
                }
            }
        }
    }
}

bool match_vertex(int v) {
    if (visited[v]) return false;
    visited[v] = true;
    for (int to : graph[v]) {
        if (match[to] == 0 || match_vertex(match[to])) {
            match[to] = v;
            return true;
        }
    }
    return false;
}

void solve_problem() {
    read_input_and_build_graph();

    int total_nodes = max_n;
    for (int i = 0; i < total_nodes; i++) {
        match_vertex(i);
        fill(visited, visited + total_nodes, false);
    }

    int total_matches = 0;
    for (int i = 0; i < total_nodes; i++) {
        if (match[i] != 0) total_matches++;
    }
    cout << total_matches;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    solve_problem();
}
